// Keccak-256 (not NIST-SHA3) hash implementation
// Used for computing Ethereum ABI function selectors and event signatures.

const RHO: [u32; 24] = [
    1, 3, 6, 10, 15, 21, 28, 36, 45, 55, 2, 14, 27, 41, 56, 8, 25, 43, 62, 18, 39, 61, 20, 44,
];

const PI: [usize; 24] = [
    10, 7, 11, 17, 18, 3, 5, 16, 8, 21, 24, 4, 15, 23, 19, 13, 12, 2, 20, 14, 22, 9, 6, 1,
];

const RC: [u64; 24] = [
    0x0000000000000001, 0x0000000000008082, 0x800000000000808a, 0x8000000080008000,
    0x000000000000808b, 0x0000000080000001, 0x8000000080008081, 0x8000000000008009,
    0x000000000000008a, 0x0000000000000088, 0x0000000080008009, 0x000000008000000a,
    0x000000008000808b, 0x800000000000008b, 0x8000000000008089, 0x8000000000008003,
    0x8000000000008002, 0x8000000000000080, 0x000000000000800a, 0x800000008000000a,
    0x8000000080008081, 0x8000000000008080, 0x0000000080000001, 0x8000000080008008,
];

fn keccak_f(state: &mut [u64; 25]) {
    for round in 0..24 {
        // Theta
        let mut bc = [0u64; 5];
        for i in 0..5 {
            bc[i] = state[i] ^ state[i + 5] ^ state[i + 10] ^ state[i + 15] ^ state[i + 20];
        }
        for i in 0..5 {
            let t = bc[(i + 4) % 5] ^ bc[(i + 1) % 5].rotate_left(1);
            for j in (0..25).step_by(5) {
                state[j + i] ^= t;
            }
        }
        // Rho + Pi
        let mut t = state[1];
        for i in 0..24 {
            let j = PI[i];
            let tmp = state[j];
            state[j] = t.rotate_left(RHO[i]);
            t = tmp;
        }
        // Chi
        for j in (0..25).step_by(5) {
            let mut s = [0u64; 5];
            for i in 0..5 {
                s[i] = state[j + i];
            }
            for i in 0..5 {
                state[j + i] ^= (!s[(i + 1) % 5]) & s[(i + 2) % 5];
            }
        }
        // Iota
        state[0] ^= RC[round];
    }
}

pub fn keccak256(data: &[u8]) -> [u8; 32] {
    let rate = 136; // 1088 bits
    let mut state = [0u64; 25];

    let mut offset = 0;
    while data.len() - offset >= rate {
        for i in 0..rate / 8 {
            let mut lane = 0u64;
            for b in 0..8 {
                lane |= (data[offset + i * 8 + b] as u64) << (8 * b);
            }
            state[i] ^= lane;
        }
        keccak_f(&mut state);
        offset += rate;
    }

    // Pad the last block
    let mut block = [0u8; 136];
    let remaining = data.len() - offset;
    block[..remaining].copy_from_slice(&data[offset..]);
    block[remaining] = 0x01; // Keccak padding (domain-less)
    block[rate - 1] |= 0x80;

    for i in 0..rate / 8 {
        let mut lane = 0u64;
        for b in 0..8 {
            lane |= (block[i * 8 + b] as u64) << (8 * b);
        }
        state[i] ^= lane;
    }
    keccak_f(&mut state);

    let mut out = [0u8; 32];
    for i in 0..4 {
        for b in 0..8 {
            out[i * 8 + b] = (state[i] >> (8 * b)) as u8;
        }
    }
    out
}
