// Hex encoding/decoding utilities.

use std::fmt;

#[derive(Debug)]
pub enum HexError {
    Odd,
    Invalid(char, usize),
}

impl fmt::Display for HexError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            HexError::Odd => write!(f, "Odd number of digits"),
            HexError::Invalid(c, p) => write!(f, "Invalid character '{}' at position {}", c, p),
        }
    }
}

pub fn decode(s: &str) -> Result<Vec<u8>, HexError> {
    // iterate by character positions (ASCII only)
    let bytes = s.as_bytes();
    if bytes.len() % 2 != 0 {
        return Err(HexError::Odd);
