// 256-bit unsigned integer arithmetic, stored as [u8; 32] big-endian.

use std::fmt;

pub type U256 = [u8; 32];

#[derive(Debug)]
pub enum UintError {
    InvalidCharacter,
    InvalidLength,
}

impl fmt::Display for UintError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            UintError::InvalidCharacter => write!(f, "InvalidCharacter"),
            UintError::InvalidLength => write!(f, "InvalidLength"),
        }
    }
}

pub fn zero() -> U256 {
    [0u8; 32]
}

/// Parse a decimal non-negative integer into a 32-byte big-endian U256.
pub fn from_dec_str(s: &str) -> Result<U256, UintError> {
    if s.is_empty() {
        return Err(UintError::InvalidCharacter);
    }
    let mut out = [0u8; 32];
    for c in s.chars() {
        if !c.is_ascii_digit() {
            return Err(UintError::InvalidCharacter);
        }
        // out = out * 10 + digit
        mul_small(&mut out, 10);
        let d = (c as u8 - b'0') as u16;
        add_small(&mut out, d);
    }
    Ok(out)
}

/// Parse a signed decimal integer; returns 2's complement U256 representation.
pub fn from_dec_str_signed(s: &str) -> Result<U256, UintError> {
    let (negative, body) = match s.as_bytes().first() {
        Some(b'-') => (true, &s[1..]),
        Some(b'+') => (false, &s[1..]),
        _ => (false, s),
    };
    let val = from_dec_str(body)?;
    if negative {
        Ok(neg(&val))
    } else {
        Ok(val)
    }
}

fn mul_small(n: &mut U256, m: u16) {
    let mut carry: u32 = 0;
    for i in (0..32).rev() {
        let prod = n[i] as u32 * m as u32 + carry;
        n[i] = prod as u8;
        carry = prod >> 8;
    }
    // overflow silently ignored to match reference behavior when lenient
}

fn add_small(n: &mut U256, v: u16) {
    let mut carry: u32 = v as u32;
    for i in (0..32).rev() {
        let s = n[i] as u32 + carry;
        n[i] = s as u8;
        carry = s >> 8;
        if carry == 0 {
            break;
        }
    }
}

pub fn neg(n: &U256) -> U256 {
    let mut out = [0u8; 32];
    for i in 0..32 {
        out[i] = !n[i];
    }
    add_small(&mut out, 1);
    out
}

/// Format a 32-byte value as hex without leading zero bytes; minimum output is "0".
pub fn to_trim_hex(n: &U256) -> String {
    let mut start = 0;
    while start < 31 && n[start] == 0 {
        start += 1;
    }
    let trimmed = &n[start..];
    // If the most significant nibble is zero and there is more than one nibble, skip it.
    let mut s = String::new();
    let mut skip_nibble = trimmed.len() > 1 && (trimmed[0] >> 4) == 0;
    for (i, b) in trimmed.iter().enumerate() {
        let hi = (b >> 4) & 0xf;
        let lo = b & 0xf;
        if !(i == 0 && skip_nibble) {
            s.push(hex_char(hi));
        } else {
            skip_nibble = false;
        }
        s.push(hex_char(lo));
    }
    if s.is_empty() {
        s.push('0');
    }
    s
}

fn hex_char(n: u8) -> char {
    match n {
        0..=9 => (b'0' + n) as char,
        10..=15 => (b'a' + n - 10) as char,
        _ => unreachable!(),
    }
}
