// Minimal JSON parser, sufficient for parsing Ethereum ABI documents.

use std::collections::BTreeMap;
use std::fmt;

#[derive(Debug, Clone)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(BTreeMap<String, Value>),
}

#[derive(Debug)]
pub struct JsonError {
    pub message: String,
}

impl fmt::Display for JsonError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl std::error::Error for JsonError {}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
}

pub fn parse(s: &str) -> Result<Value, JsonError> {
    let mut p = Parser { input: s.as_bytes(), pos: 0 };
    p.skip_ws();
    let v = p.parse_value()?;
    p.skip_ws();
    if p.pos != p.input.len() {
        return Err(JsonError { message: format!("trailing data at {}", p.pos) });
    }
    Ok(v)
}

impl<'a> Parser<'a> {
    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn err(&self, msg: &str) -> JsonError {
        JsonError { message: format!("{} at {}", msg, self.pos) }
    }

    fn parse_value(&mut self) -> Result<Value, JsonError> {
        self.skip_ws();
        if self.pos >= self.input.len() {
            return Err(self.err("unexpected end of input"));
        }
        match self.input[self.pos] {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => self.parse_string().map(Value::String),
            b't' | b'f' => self.parse_bool(),
            b'n' => self.parse_null(),
            b'-' | b'0'..=b'9' => self.parse_number(),
            c => Err(self.err(&format!("unexpected character '{}'", c as char))),
        }
    }

    fn parse_object(&mut self) -> Result<Value, JsonError> {
        self.pos += 1;
        let mut map = BTreeMap::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.pos += 1;
            return Ok(Value::Object(map));
        }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.pos >= self.input.len() || self.input[self.pos] != b':' {
                return Err(self.err("expected ':'"));
            }
            self.pos += 1;
            let value = self.parse_value()?;
            map.insert(key, value);
            self.skip_ws();
            if self.pos >= self.input.len() {
                return Err(self.err("unterminated object"));
            }
            match self.input[self.pos] {
                b',' => { self.pos += 1; continue; }
                b'}' => { self.pos += 1; return Ok(Value::Object(map)); }
                c => return Err(self.err(&format!("expected ',' or '}}' got '{}'", c as char))),
            }
        }
    }

    fn parse_array(&mut self) -> Result<Value, JsonError> {
        self.pos += 1;
        let mut arr = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.pos += 1;
            return Ok(Value::Array(arr));
        }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            if self.pos >= self.input.len() {
                return Err(self.err("unterminated array"));
            }
            match self.input[self.pos] {
                b',' => { self.pos += 1; continue; }
                b']' => { self.pos += 1; return Ok(Value::Array(arr)); }
                c => return Err(self.err(&format!("expected ',' or ']' got '{}'", c as char))),
            }
        }
    }

    fn parse_string(&mut self) -> Result<String, JsonError> {
        if self.pos >= self.input.len() || self.input[self.pos] != b'"' {
            return Err(self.err("expected '\"'"));
        }
        self.pos += 1;
        let mut out = Vec::new();
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b'"' => { self.pos += 1; return Ok(String::from_utf8_lossy(&out).into_owned()); }
                b'\\' => {
                    self.pos += 1;
                    if self.pos >= self.input.len() {
                        return Err(self.err("unterminated escape"));
                    }
                    match self.input[self.pos] {
                        b'"' => out.push(b'"'),
                        b'\\' => out.push(b'\\'),
                        b'/' => out.push(b'/'),
                        b'n' => out.push(b'\n'),
                        b't' => out.push(b'\t'),
                        b'r' => out.push(b'\r'),
                        b'b' => out.push(0x08),
                        b'f' => out.push(0x0c),
                        b'u' => {
                            if self.pos + 4 >= self.input.len() {
                                return Err(self.err("bad unicode escape"));
                            }
                            let hex = std::str::from_utf8(&self.input[self.pos + 1..self.pos + 5])
                                .map_err(|_| self.err("bad unicode escape"))?;
                            let code = u32::from_str_radix(hex, 16)
                                .map_err(|_| self.err("bad unicode escape"))?;
                            if let Some(c) = char::from_u32(code) {
                                let mut buf = [0u8; 4];
                                let s = c.encode_utf8(&mut buf);
                                out.extend_from_slice(s.as_bytes());
                            }
                            self.pos += 4;
                        }
                        c => return Err(self.err(&format!("bad escape '\\{}'", c as char))),
                    }
                    self.pos += 1;
                }
                c => { out.push(c); self.pos += 1; }
            }
        }
        Err(self.err("unterminated string"))
    }

    fn parse_bool(&mut self) -> Result<Value, JsonError> {
        if self.input[self.pos..].starts_with(b"true") {
            self.pos += 4;
            Ok(Value::Bool(true))
        } else if self.input[self.pos..].starts_with(b"false") {
            self.pos += 5;
            Ok(Value::Bool(false))
        } else {
            Err(self.err("invalid bool"))
        }
    }

    fn parse_null(&mut self) -> Result<Value, JsonError> {
        if self.input[self.pos..].starts_with(b"null") {
            self.pos += 4;
            Ok(Value::Null)
        } else {
            Err(self.err("invalid null"))
        }
    }

    fn parse_number(&mut self) -> Result<Value, JsonError> {
        let start = self.pos;
        if self.input[self.pos] == b'-' {
            self.pos += 1;
        }
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c.is_ascii_digit() || c == b'.' || c == b'e' || c == b'E' || c == b'+' || c == b'-' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos])
            .map_err(|_| self.err("invalid number"))?;
        let n: f64 = s.parse().map_err(|_| self.err("invalid number"))?;
        Ok(Value::Number(n))
    }
}

impl Value {
    pub fn as_array(&self) -> Option<&Vec<Value>> {
        if let Value::Array(a) = self { Some(a) } else { None }
    }
    pub fn as_object(&self) -> Option<&BTreeMap<String, Value>> {
        if let Value::Object(o) = self { Some(o) } else { None }
    }
    pub fn as_str(&self) -> Option<&str> {
        if let Value::String(s) = self { Some(s) } else { None }
    }
    pub fn as_bool(&self) -> Option<bool> {
        if let Value::Bool(b) = self { Some(*b) } else { None }
    }
}
