// ABI type parser.

use std::fmt;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParamType {
    Address,
    Bytes,
    Int(usize),
    Uint(usize),
    Bool,
    String,
    Array(Box<ParamType>),
    FixedBytes(usize),
    FixedArray(Box<ParamType>, usize),
    Tuple(Vec<ParamType>),
}

#[derive(Debug)]
pub struct TypeParseError(pub String);

impl fmt::Display for TypeParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl std::error::Error for TypeParseError {}

impl fmt::Display for ParamType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParamType::Address => write!(f, "address"),
            ParamType::Bytes => write!(f, "bytes"),
            ParamType::Int(n) => write!(f, "int{}", n),
            ParamType::Uint(n) => write!(f, "uint{}", n),
            ParamType::Bool => write!(f, "bool"),
            ParamType::String => write!(f, "string"),
            ParamType::Array(inner) => write!(f, "{}[]", inner),
            ParamType::FixedBytes(n) => write!(f, "bytes{}", n),
            ParamType::FixedArray(inner, n) => write!(f, "{}[{}]", inner, n),
            ParamType::Tuple(inner) => {
                write!(f, "(")?;
                for (i, t) in inner.iter().enumerate() {
                    if i > 0 { write!(f, ",")?; }
                    write!(f, "{}", t)?;
                }
                write!(f, ")")
            }
        }
    }
}

impl ParamType {
    /// Is this type dynamic, per Solidity ABI v2.
    pub fn is_dynamic(&self) -> bool {
        match self {
            ParamType::Bytes | ParamType::String => true,
            ParamType::Array(_) => true,
            ParamType::FixedArray(inner, _) => inner.is_dynamic(),
            ParamType::Tuple(types) => types.iter().any(|t| t.is_dynamic()),
            _ => false,
        }
    }
}

pub fn parse(s: &str) -> Result<ParamType, TypeParseError> {
    let (t, rest) = parse_inner(s)?;
    if !rest.is_empty() {
        return Err(TypeParseError(format!("unexpected trailing characters: {}", rest)));
    }
    Ok(t)
}

fn parse_inner(s: &str) -> Result<(ParamType, &str), TypeParseError> {
    let (base, mut rest) = if s.starts_with('(') {
        let (types, after) = parse_tuple(s)?;
        (ParamType::Tuple(types), after)
    } else {
        parse_simple(s)?
    };

    let mut current = base;
    // Handle array suffixes: [] or [N]
    loop {
        if !rest.starts_with('[') {
            break;
        }
        let end = rest.find(']').ok_or_else(|| TypeParseError("unmatched '['".to_string()))?;
        let size_str = &rest[1..end];
        if size_str.is_empty() {
            current = ParamType::Array(Box::new(current));
        } else {
            let n: usize = size_str.parse().map_err(|_| TypeParseError(format!("bad array size '{}'", size_str)))?;
            current = ParamType::FixedArray(Box::new(current), n);
        }
        rest = &rest[end + 1..];
    }

    Ok((current, rest))
}

fn parse_simple(s: &str) -> Result<(ParamType, &str), TypeParseError> {
    // Find end of identifier (first char that is not [a-zA-Z0-9])
    let end = s.find(|c: char| !c.is_ascii_alphanumeric()).unwrap_or(s.len());
    let (id, rest) = s.split_at(end);
    let t = match id {
        "address" => ParamType::Address,
        "bool" => ParamType::Bool,
        "string" => ParamType::String,
        "bytes" => ParamType::Bytes,
        _ => {
            if let Some(rest_n) = id.strip_prefix("bytes") {
                let n: usize = rest_n.parse().map_err(|_| TypeParseError(format!("invalid type {}", id)))?;
                ParamType::FixedBytes(n)
            } else if let Some(rest_n) = id.strip_prefix("uint") {
                let n: usize = if rest_n.is_empty() { 256 } else {
                    rest_n.parse().map_err(|_| TypeParseError(format!("invalid type {}", id)))?
                };
                ParamType::Uint(n)
            } else if let Some(rest_n) = id.strip_prefix("int") {
                let n: usize = if rest_n.is_empty() { 256 } else {
                    rest_n.parse().map_err(|_| TypeParseError(format!("invalid type {}", id)))?
                };
                ParamType::Int(n)
            } else {
                return Err(TypeParseError(format!("invalid type '{}'", id)));
            }
        }
    };
    Ok((t, rest))
}

fn parse_tuple(s: &str) -> Result<(Vec<ParamType>, &str), TypeParseError> {
    // s starts with '('
    assert!(s.starts_with('('));
    let mut rest = &s[1..];
    let mut parts = Vec::new();

    // Empty tuple "()"
    if rest.starts_with(')') {
        return Ok((parts, &rest[1..]));
    }

    loop {
        let (t, after) = parse_inner(rest)?;
        parts.push(t);
        rest = after;
        if rest.starts_with(',') {
            rest = &rest[1..];
            continue;
        } else if rest.starts_with(')') {
            return Ok((parts, &rest[1..]));
        } else {
            return Err(TypeParseError(format!("expected ',' or ')' in tuple, got '{}'", rest)));
        }
    }
}
