// ABI tokens and parsing from user input.

use crate::abi_type::ParamType;
use crate::hex;
use crate::uint;

#[derive(Debug, Clone)]
pub enum Token {
    Address([u8; 20]),
    FixedBytes(Vec<u8>),
    Bytes(Vec<u8>),
    Int([u8; 32]),
    Uint([u8; 32]),
    Bool(bool),
    String(String),
    FixedArray(Vec<Token>),
    Array(Vec<Token>),
    Tuple(Vec<Token>),
}

impl Token {
    pub fn type_check(&self, t: &ParamType) -> bool {
        match (self, t) {
            (Token::Address(_), ParamType::Address) => true,
            (Token::Bool(_), ParamType::Bool) => true,
            (Token::String(_), ParamType::String) => true,
            (Token::Bytes(_), ParamType::Bytes) => true,
            (Token::FixedBytes(b), ParamType::FixedBytes(n)) => b.len() == *n,
            (Token::Uint(_), ParamType::Uint(_)) => true,
            (Token::Int(_), ParamType::Int(_)) => true,
            (Token::Array(arr), ParamType::Array(inner)) => arr.iter().all(|x| x.type_check(inner)),
            (Token::FixedArray(arr), ParamType::FixedArray(inner, n)) => {
                arr.len() == *n && arr.iter().all(|x| x.type_check(inner))
            }
            (Token::Tuple(ts), ParamType::Tuple(pts)) => {
                ts.len() == pts.len() && ts.iter().zip(pts.iter()).all(|(x, p)| x.type_check(p))
            }
            _ => false,
        }
    }
}

#[derive(Debug)]
pub enum TokenError {
    HexError(crate::hex::HexError),
    UintError(uint::UintError),
    InvalidData,
}

impl std::fmt::Display for TokenError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TokenError::HexError(e) => write!(f, "Hex parsing error: {}", e),
            TokenError::UintError(e) => write!(f, "Uint parse error: {}", e),
            TokenError::InvalidData => write!(f, "Invalid data"),
        }
    }
}

impl std::error::Error for TokenError {}

impl From<crate::hex::HexError> for TokenError {
    fn from(e: crate::hex::HexError) -> Self { TokenError::HexError(e) }
}

/// Split an input string of the form `[a,b,c]`, `(a,b,c)`, or a single primitive into pieces.
/// Handles nested brackets and parens.
fn split_items(s: &str, open: char, close: char) -> Option<Vec<String>> {
    if !s.starts_with(open) || !s.ends_with(close) {
        return None;
    }
    let inner = &s[open.len_utf8()..s.len() - close.len_utf8()];
    if inner.is_empty() {
        return Some(Vec::new());
    }
    let mut parts = Vec::new();
    let mut depth_sq: i32 = 0;
    let mut depth_pa: i32 = 0;
    let mut start = 0;
    let bytes = inner.as_bytes();
    for i in 0..bytes.len() {
        match bytes[i] {
            b'[' => depth_sq += 1,
            b']' => depth_sq -= 1,
            b'(' => depth_pa += 1,
            b')' => depth_pa -= 1,
            b',' if depth_sq == 0 && depth_pa == 0 => {
                parts.push(inner[start..i].to_string());
                start = i + 1;
            }
            _ => {}
        }
    }
    parts.push(inner[start..].to_string());
    Some(parts)
}

/// Parse a user-supplied token for the given ABI type.
pub fn tokenize(t: &ParamType, s: &str, lenient: bool) -> Result<Token, TokenError> {
    match t {
        ParamType::Bool => parse_bool(s),
        ParamType::Address => parse_address(s),
        ParamType::String => Ok(Token::String(s.to_string())),
        ParamType::Bytes => {
            let bytes = hex::decode(s)?;
            Ok(Token::Bytes(bytes))
        }
        ParamType::FixedBytes(n) => {
            let bytes = hex::decode(s)?;
            if bytes.len() != *n {
                return Err(TokenError::InvalidData);
            }
            Ok(Token::FixedBytes(bytes))
        }
        ParamType::Uint(_) => parse_uint(s, lenient),
        ParamType::Int(_) => parse_int(s, lenient),
        ParamType::Array(inner) => {
            let parts = split_items(s, '[', ']').ok_or(TokenError::InvalidData)?;
            let mut out = Vec::new();
            for p in parts {
                out.push(tokenize(inner, &p, lenient)?);
            }
            Ok(Token::Array(out))
        }
        ParamType::FixedArray(inner, n) => {
            let parts = split_items(s, '[', ']').ok_or(TokenError::InvalidData)?;
            if parts.len() != *n {
                return Err(TokenError::InvalidData);
            }
            let mut out = Vec::new();
            for p in parts {
                out.push(tokenize(inner, &p, lenient)?);
            }
            Ok(Token::FixedArray(out))
        }
        ParamType::Tuple(types) => {
            let parts = split_items(s, '(', ')').ok_or(TokenError::InvalidData)?;
            if parts.len() != types.len() {
                return Err(TokenError::InvalidData);
            }
            let mut out = Vec::new();
            for (p, t) in parts.iter().zip(types.iter()) {
                out.push(tokenize(t, p, lenient)?);
            }
            Ok(Token::Tuple(out))
        }
    }
}

fn parse_bool(s: &str) -> Result<Token, TokenError> {
    match s {
        "true" | "1" => Ok(Token::Bool(true)),
        "false" | "0" => Ok(Token::Bool(false)),
        _ => Err(TokenError::InvalidData),
    }
}

fn parse_address(s: &str) -> Result<Token, TokenError> {
    let stripped = s.strip_prefix("0x").unwrap_or(s);
    let bytes = hex::decode(stripped)?;
    if bytes.len() != 20 {
        return Err(TokenError::InvalidData);
    }
    let mut arr = [0u8; 20];
    arr.copy_from_slice(&bytes);
    Ok(Token::Address(arr))
}

fn parse_uint(s: &str, lenient: bool) -> Result<Token, TokenError> {
    if lenient {
        let v = uint::from_dec_str(s).map_err(TokenError::UintError)?;
        Ok(Token::Uint(v))
    } else {
        let bytes = hex::decode(s)?;
        if bytes.len() != 32 {
            return Err(TokenError::InvalidData);
        }
        let mut arr = [0u8; 32];
        arr.copy_from_slice(&bytes);
        Ok(Token::Uint(arr))
    }
}

fn parse_int(s: &str, lenient: bool) -> Result<Token, TokenError> {
    if lenient {
        let v = uint::from_dec_str_signed(s).map_err(TokenError::UintError)?;
        Ok(Token::Int(v))
    } else {
        let bytes = hex::decode(s)?;
        if bytes.len() != 32 {
            return Err(TokenError::InvalidData);
        }
        let mut arr = [0u8; 32];
        arr.copy_from_slice(&bytes);
        Ok(Token::Int(arr))
    }
}

/// Format a token for display (after decoding).
pub fn format_token(t: &Token) -> String {
    match t {
        Token::Address(a) => hex::encode(a),
        Token::Bool(b) => if *b { "true".to_string() } else { "false".to_string() },
        Token::String(s) => s.clone(),
        Token::Bytes(b) => hex::encode(b),
        Token::FixedBytes(b) => hex::encode(b),
        Token::Uint(v) => uint::to_trim_hex(v),
        Token::Int(v) => uint::to_trim_hex(v),
        Token::Array(items) | Token::FixedArray(items) => {
            let parts: Vec<String> = items.iter().map(format_token).collect();
            format!("[{}]", parts.join(","))
        }
        Token::Tuple(items) => {
            let parts: Vec<String> = items.iter().map(format_token).collect();
            format!("({})", parts.join(","))
        }
    }
}
