// ABI encoder.

use crate::token::Token;
use crate::abi_type::ParamType;

/// Encode a list of tokens.
pub fn encode(tokens: &[Token]) -> Vec<u8> {
    let mut mediates: Vec<Mediate> = tokens.iter().map(encode_token).collect();
    collect(&mut mediates)
}

fn collect(mediates: &mut Vec<Mediate>) -> Vec<u8> {
    // Compute head size
    let head_size: usize = mediates.iter().map(Mediate::head_size).sum();
    let mut out = Vec::new();
    let mut tail = Vec::new();

    for m in mediates.iter() {
        match m {
            Mediate::Raw(data) => out.extend_from_slice(data),
            Mediate::Prefixed { .. } => {
                let offset = head_size + tail.len();
                out.extend_from_slice(&u256_from_usize(offset));
                tail.extend_from_slice(&m.tail_bytes());
            }
        }
    }
    out.extend_from_slice(&tail);
    out
}

#[derive(Debug)]
enum Mediate {
    Raw(Vec<u8>),
    Prefixed { tail: Vec<u8> },
}

impl Mediate {
    fn head_size(&self) -> usize {
        match self {
            Mediate::Raw(data) => data.len(),
            Mediate::Prefixed { .. } => 32,
        }
    }
    fn tail_bytes(&self) -> Vec<u8> {
        match self {
            Mediate::Raw(_) => Vec::new(),
            Mediate::Prefixed { tail } => tail.clone(),
        }
    }
}

fn u256_from_usize(n: usize) -> [u8; 32] {
    let mut buf = [0u8; 32];
    for i in 0..8 {
        buf[31 - i] = (n >> (8 * i)) as u8;
    }
    buf
}

pub fn encode_token(token: &Token) -> Mediate {
    match token {
        Token::Address(a) => {
            let mut buf = [0u8; 32];
            buf[12..].copy_from_slice(a);
            Mediate::Raw(buf.to_vec())
        }
        Token::Bool(b) => {
            let mut buf = [0u8; 32];
            if *b { buf[31] = 1; }
            Mediate::Raw(buf.to_vec())
        }
        Token::Uint(v) | Token::Int(v) => Mediate::Raw(v.to_vec()),
        Token::FixedBytes(b) => {
            let mut buf = vec![0u8; 32];
            buf[..b.len()].copy_from_slice(b);
            Mediate::Raw(buf)
        }
        Token::Bytes(b) => {
            let mut tail = Vec::new();
            tail.extend_from_slice(&u256_from_usize(b.len()));
            tail.extend_from_slice(b);
            // pad to 32
            let pad = (32 - (b.len() % 32)) % 32;
            if pad != 0 { tail.resize(tail.len() + pad, 0); }
            Mediate::Prefixed { tail }
        }
        Token::String(s) => {
            let b = s.as_bytes();
            let mut tail = Vec::new();
            tail.extend_from_slice(&u256_from_usize(b.len()));
            tail.extend_from_slice(b);
            let pad = (32 - (b.len() % 32)) % 32;
            if pad != 0 { tail.resize(tail.len() + pad, 0); }
            Mediate::Prefixed { tail }
        }
        Token::Array(items) => {
