// ABI decoder.

use crate::abi_type::ParamType;
use crate::token::Token;

#[derive(Debug)]
pub struct DecodeError(pub String);

impl std::fmt::Display for DecodeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl std::error::Error for DecodeError {}

fn check_len(data: &[u8], offset: usize, len: usize) -> Result<(), DecodeError> {
    if offset + len > data.len() {
        return Err(DecodeError("Invalid data".to_string()));
    }
    Ok(())
}

fn slot(data: &[u8], offset: usize) -> Result<&[u8], DecodeError> {
    check_len(data, offset, 32)?;
    Ok(&data[offset..offset + 32])
}

fn as_usize(slot: &[u8]) -> Result<usize, DecodeError> {
    // First 24 bytes must be zero-ish (for a valid offset/length, they will be).
    for i in 0..28 {
        if slot[i] != 0 {
            // A length/offset exceeding usize is an error.
            return Err(DecodeError("Invalid data".to_string()));
        }
    }
    let mut v: u64 = 0;
    for i in 0..8 {
        v = (v << 8) | slot[24 + i] as u64;
    }
    Ok(v as usize)
}

pub fn decode(types: &[ParamType], data: &[u8]) -> Result<Vec<Token>, DecodeError> {
    let (tokens, _) = decode_params(types, data, 0)?;
    Ok(tokens)
}

/// Decode a sequence of types starting at `offset` in the given `data`.
/// Returns the tokens and the total consumed bytes in the head region.
fn decode_params(types: &[ParamType], data: &[u8], offset: usize) -> Result<(Vec<Token>, usize), DecodeError> {
    let mut tokens = Vec::with_capacity(types.len());
    let mut cur = offset;
    for t in types {
        let (tok, consumed) = decode_type(t, data, cur, offset)?;
        tokens.push(tok);
        cur += consumed;
    }
    Ok((tokens, cur - offset))
}

/// Decode a single parameter.
/// `head_offset` is the current position in the head region.
/// `params_offset` is the start of the parameter group (for dynamic offset reference).
fn decode_type(t: &ParamType, data: &[u8], head_offset: usize, params_offset: usize) -> Result<(Token, usize), DecodeError> {
    match t {
        ParamType::Address => {
            let s = slot(data, head_offset)?;
            let mut a = [0u8; 20];
            a.copy_from_slice(&s[12..]);
            Ok((Token::Address(a), 32))
        }
        ParamType::Bool => {
            let s = slot(data, head_offset)?;
            Ok((Token::Bool(s[31] == 1), 32))
        }
        ParamType::Uint(_) => {
            let s = slot(data, head_offset)?;
            let mut v = [0u8; 32];
            v.copy_from_slice(s);
            Ok((Token::Uint(v), 32))
        }
        ParamType::Int(_) => {
            let s = slot(data, head_offset)?;
            let mut v = [0u8; 32];
            v.copy_from_slice(s);
            Ok((Token::Int(v), 32))
        }
        ParamType::FixedBytes(n) => {
            let s = slot(data, head_offset)?;
            let v = s[..*n].to_vec();
            Ok((Token::FixedBytes(v), 32))
        }
        ParamType::Bytes => {
            let off_slot = slot(data, head_offset)?;
            let off = as_usize(off_slot)?;
            let start = params_offset + off;
            let len_slot = slot(data, start)?;
            let len = as_usize(len_slot)?;
            check_len(data, start + 32, len)?;
            let v = data[start + 32..start + 32 + len].to_vec();
            Ok((Token::Bytes(v), 32))
        }
        ParamType::String => {
            let off_slot = slot(data, head_offset)?;
            let off = as_usize(off_slot)?;
            let start = params_offset + off;
            let len_slot = slot(data, start)?;
            let len = as_usize(len_slot)?;
            check_len(data, start + 32, len)?;
            let s = String::from_utf8(data[start + 32..start + 32 + len].to_vec())
                .map_err(|_| DecodeError("Invalid data".to_string()))?;
            Ok((Token::String(s), 32))
        }
        ParamType::Array(inner) => {
            let off_slot = slot(data, head_offset)?;
            let off = as_usize(off_slot)?;
            let start = params_offset + off;
            let len = as_usize(slot(data, start)?)?;
            let items_offset = start + 32;
            let mut items = Vec::with_capacity(len);
            let mut cur = items_offset;
            for _ in 0..len {
                let (tok, consumed) = decode_type(inner, data, cur, items_offset)?;
                items.push(tok);
                cur += consumed;
            }
            Ok((Token::Array(items), 32))
        }
        ParamType::FixedArray(inner, n) => {
            if inner.is_dynamic() {
                let off_slot = slot(data, head_offset)?;
                let off = as_usize(off_slot)?;
                let start = params_offset + off;
                let mut items = Vec::with_capacity(*n);
                let mut cur = start;
                for _ in 0..*n {
                    let (tok, consumed) = decode_type(inner, data, cur, start)?;
                    items.push(tok);
                    cur += consumed;
                }
                Ok((Token::FixedArray(items), 32))
            } else {
                let mut items = Vec::with_capacity(*n);
                let mut cur = head_offset;
                let mut total = 0;
                for _ in 0..*n {
                    let (tok, consumed) = decode_type(inner, data, cur, params_offset)?;
                    items.push(tok);
                    cur += consumed;
                    total += consumed;
                }
                Ok((Token::FixedArray(items), total))
            }
        }
        ParamType::Tuple(inner) => {
            if t.is_dynamic() {
                let off_slot = slot(data, head_offset)?;
                let off = as_usize(off_slot)?;
                let start = params_offset + off;
                let (items, _) = decode_params(inner, data, start)?;
                Ok((Token::Tuple(items), 32))
            } else {
                let (items, consumed) = decode_params(inner, data, head_offset)?;
                Ok((Token::Tuple(items), consumed))
            }
        }
    }
}
