// ABI contract file parsing.

use crate::abi_type::ParamType;
use crate::json::Value;

#[derive(Debug, Clone)]
pub struct Param {
    pub name: String,
    pub kind: ParamType,
    pub indexed: bool,
}

#[derive(Debug, Clone)]
pub struct Function {
    pub name: String,
    pub inputs: Vec<Param>,
    pub outputs: Vec<Param>,
}

#[derive(Debug, Clone)]
pub struct Event {
    pub name: String,
    pub inputs: Vec<Param>,
    pub anonymous: bool,
}

#[derive(Debug, Clone)]
pub struct Constructor {
    pub inputs: Vec<Param>,
}

#[derive(Debug, Clone, Default)]
pub struct Contract {
    pub functions: Vec<Function>,
    pub events: Vec<Event>,
    pub constructor: Option<Constructor>,
}

#[derive(Debug)]
pub struct ContractError(pub String);

impl std::fmt::Display for ContractError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl std::error::Error for ContractError {}

pub fn parse_contract(src: &str) -> Result<Contract, Box<dyn std::error::Error>> {
    let v = crate::json::parse(src)?;
    let arr = v.as_array().ok_or_else(|| ContractError("top-level must be array".to_string()))?;
    let mut contract = Contract::default();

    for item in arr {
        let obj = item.as_object().ok_or_else(|| ContractError("ABI item must be object".to_string()))?;
        let kind = obj.get("type").and_then(|v| v.as_str()).unwrap_or("function");
        match kind {
            "function" => {
                let name = obj.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let inputs = parse_params(obj.get("inputs"))?;
                let outputs = parse_params(obj.get("outputs"))?;
                contract.functions.push(Function { name, inputs, outputs });
            }
            "event" => {
                let name = obj.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let inputs = parse_params(obj.get("inputs"))?;
                let anonymous = obj.get("anonymous").and_then(|v| v.as_bool()).unwrap_or(false);
                contract.events.push(Event { name, inputs, anonymous });
            }
            "constructor" => {
                let inputs = parse_params(obj.get("inputs"))?;
                contract.constructor = Some(Constructor { inputs });
            }
            "fallback" | "receive" | "error" => {
                // ignored
            }
            _ => {}
        }
    }
    Ok(contract)
}

fn parse_params(v: Option<&Value>) -> Result<Vec<Param>, ContractError> {
    let arr = match v {
        Some(Value::Array(a)) => a,
        _ => return Ok(Vec::new()),
    };
    let mut out = Vec::new();
    for p in arr {
        let obj = p.as_object().ok_or_else(|| ContractError("param must be object".to_string()))?;
        let name = obj.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
        let type_str = obj.get("type").and_then(|v| v.as_str())
            .ok_or_else(|| ContractError("param missing type".to_string()))?;
        let indexed = obj.get("indexed").and_then(|v| v.as_bool()).unwrap_or(false);
        let kind = parse_type(type_str, obj.get("components"))?;
        out.push(Param { name, kind, indexed });
    }
    Ok(out)
}

fn parse_type(type_str: &str, components: Option<&Value>) -> Result<ParamType, ContractError> {
    // Handle tuple / tuple[] / tuple[N] etc via components.
    if let Some(rest) = type_str.strip_prefix("tuple") {
        // rest is any trailing "[]" / "[N]" etc.
        let comps = components.and_then(|v| v.as_array()).ok_or_else(|| ContractError("tuple requires components".to_string()))?;
        let mut inner_types = Vec::new();
        for c in comps {
            let co = c.as_object().ok_or_else(|| ContractError("component must be object".to_string()))?;
            let t = co.get("type").and_then(|v| v.as_str())
                .ok_or_else(|| ContractError("component missing type".to_string()))?;
            let inner_comp = co.get("components");
            inner_types.push(parse_type(t, inner_comp)?);
        }
        let mut result = ParamType::Tuple(inner_types);
        // Apply array suffixes from `rest`
        let mut rem = rest;
        while !rem.is_empty() {
            if !rem.starts_with('[') {
                return Err(ContractError(format!("bad tuple array suffix {}", rem)));
            }
            let end = rem.find(']').ok_or_else(|| ContractError("unterminated [".to_string()))?;
            let size_str = &rem[1..end];
            if size_str.is_empty() {
                result = ParamType::Array(Box::new(result));
            } else {
                let n: usize = size_str.parse().map_err(|_| ContractError(format!("bad array size {}", size_str)))?;
                result = ParamType::FixedArray(Box::new(result), n);
            }
            rem = &rem[end + 1..];
        }
        Ok(result)
    } else {
        crate::abi_type::parse(type_str).map_err(|e| ContractError(e.0))
    }
}

impl Function {
    pub fn signature(&self) -> String {
        let mut s = String::new();
        s.push_str(&self.name);
        s.push('(');
        for (i, p) in self.inputs.iter().enumerate() {
            if i > 0 { s.push(','); }
            s.push_str(&format!("{}", p.kind));
        }
        s.push(')');
        s
    }

    pub fn signature_with_outputs(&self) -> String {
        // name(intypes):(outtypes) if outputs present, else name(intypes)
        let mut s = self.signature();
        if !self.outputs.is_empty() {
            s.push_str(":(");
            for (i, p) in self.outputs.iter().enumerate() {
                if i > 0 { s.push(','); }
                s.push_str(&format!("{}", p.kind));
            }
            s.push(')');
        }
        s
    }

    pub fn selector(&self) -> [u8; 4] {
        let sig = self.signature();
        let h = crate::keccak::keccak256(sig.as_bytes());
        [h[0], h[1], h[2], h[3]]
    }
}

impl Event {
    pub fn signature(&self) -> String {
        let mut s = String::new();
        s.push_str(&self.name);
        s.push('(');
        for (i, p) in self.inputs.iter().enumerate() {
            if i > 0 { s.push(','); }
            s.push_str(&format!("{}", p.kind));
        }
        s.push(')');
        s
    }

    pub fn topic_hash(&self) -> [u8; 32] {
        crate::keccak::keccak256(self.signature().as_bytes())
    }
}
