use std::process::ExitCode;

const VERSION: &str = "18.0.0";

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().collect();

    match run(&args) {
        Ok(code) => code,
        Err(e) => {
            eprintln!("Error: {}", e);
            if let Some(src) = e.source() {
                eprintln!();
                eprintln!("Caused by:");
                eprintln!("    {}", src);
            }
            ExitCode::from(1)
        }
    }
}

fn run(args: &[String]) -> Result<ExitCode, AppError> {
    let mut args = args.iter().skip(1).cloned().collect::<Vec<_>>();

    if args.is_empty() {
        print_top_help();
        return Ok(ExitCode::from(1));
    }

    // Look for top-level flags
    match args[0].as_str() {
        "-h" | "--help" => { print_top_help(); return Ok(ExitCode::from(0)); }
        "-V" | "--version" => { println!("ethabi-cli {}", VERSION); return Ok(ExitCode::from(0)); }
        "help" => {
            if args.len() == 1 {
                print_top_help();
                return Ok(ExitCode::from(0));
            }
            match args[1].as_str() {
                "encode" => { if args.len() == 2 { print_encode_help(); return Ok(ExitCode::from(0)); }
                              match args[2].as_str() {
                                  "function" => { print_encode_function_help(); return Ok(ExitCode::from(0)); }
                                  "params" => { print_encode_params_help(); return Ok(ExitCode::from(0)); }
                                  "help" => { print_encode_help(); return Ok(ExitCode::from(0)); }
                                  _ => { return cli_error_unknown_help(&args[2]); }
                              } }
                "decode" => { if args.len() == 2 { print_decode_help(); return Ok(ExitCode::from(0)); }
                              match args[2].as_str() {
                                  "function" => { print_decode_function_help(); return Ok(ExitCode::from(0)); }
                                  "params" => { print_decode_params_help(); return Ok(ExitCode::from(0)); }
                                  "log" => { print_decode_log_help(); return Ok(ExitCode::from(0)); }
                                  "help" => { print_decode_help(); return Ok(ExitCode::from(0)); }
                                  _ => { return cli_error_unknown_help(&args[2]); }
                              } }
                "help" => { print_top_help(); return Ok(ExitCode::from(0)); }
                _ => { return cli_error_unknown_help(&args[1]); }
            }
        }
        "encode" => {
            args.remove(0);
            return run_encode(&args);
        }
        "decode" => {
            args.remove(0);
            return run_decode(&args);
        }
        s => {
            cli_error_unknown_subcommand(s);
            return Ok(ExitCode::from(1));
        }
    }
}

fn cli_error_unknown_subcommand(s: &str) {
    eprintln!("error: Found argument '{}' which wasn't expected, or isn't valid in this context", s);
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("    executable <SUBCOMMAND>");
    eprintln!();
    eprintln!("For more information try --help");
}

fn cli_error_unknown_help(s: &str) -> Result<ExitCode, AppError> {
    eprintln!("error: The subcommand '{}' wasn't recognized", s);
    eprintln!();
    eprintln!("For more information try --help");
    Ok(ExitCode::from(1))
}

fn run_encode(args: &[String]) -> Result<ExitCode, AppError> {
    if args.is_empty() {
        print_encode_help();
        return Ok(ExitCode::from(1));
    }
    match args[0].as_str() {
        "-h" | "--help" => { print_encode_help(); return Ok(ExitCode::from(0)); }
        "-V" | "--version" => { println!("executable-encode {}", VERSION); return Ok(ExitCode::from(0)); }
        "help" => {
            if args.len() == 1 {
                print_encode_help();
                return Ok(ExitCode::from(0));
            }
            match args[1].as_str() {
                "function" => { print_encode_function_help(); return Ok(ExitCode::from(0)); }
                "params" => { print_encode_params_help(); return Ok(ExitCode::from(0)); }
                "help" => { print_encode_help(); return Ok(ExitCode::from(0)); }
                _ => return cli_error_unknown_help(&args[1]),
            }
        }
        "function" => run_encode_function(&args[1..]),
        "params" => run_encode_params(&args[1..]),
        s => {
            cli_error_unknown_subcommand(s);
            Ok(ExitCode::from(1))
        }
    }
}

fn run_decode(args: &[String]) -> Result<ExitCode, AppError> {
    if args.is_empty() {
        print_decode_help();
        return Ok(ExitCode::from(1));
