        .map(|(p, v)| token::tokenize(&p.kind, v, lenient))
        .collect::<Result<_, _>>()
        .map_err(|e| wrap_token_error(e))?;

    let mut out = Vec::new();
    out.extend_from_slice(&func.selector());
    out.extend_from_slice(&encoder::encode(&tokens));
