    eprintln!("    executable decode params <data> -t <type>...");
    eprintln!();
    eprintln!("For more information try --help");
}

fn run_decode_log(args: &[String]) -> Result<ExitCode, AppError> {
    let mut topics: Vec<String> = Vec::new();
    let mut positional: Vec<String> = Vec::new();
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-h" | "--help" => { print_decode_log_help(); return Ok(ExitCode::from(0)); }
            "-V" | "--version" => { println!("executable-decode-log {}", VERSION); return Ok(ExitCode::from(0)); }
            "-l" => {
                if i + 1 >= args.len() {
                    return Err(AppError::new("missing value for -l"));
                }
                topics.push(args[i + 1].clone());
                i += 2;
            }
            _ => {
                positional.push(a.clone());
                i += 1;
            }
        }
    }
    if positional.len() != 3 {
        return Err(AppError::new("expected 3 positional args (abi-path, event-name-or-signature, data)"));
    }
    let abi_path = &positional[0];
    let event_sig = &positional[1];
    let data_hex = &positional[2];

    let src = std::fs::read_to_string(abi_path).map_err(|e| AppError::new(e.to_string()))?;
    let contract = contract::parse_contract(&src).map_err(wrap_serialization_error)?;

    let event = find_event(&contract, event_sig)?;

    // Parse topics
    let mut topic_bytes: Vec<[u8; 32]> = Vec::new();
    for t in &topics {
        let b = hex::decode(t).map_err(wrap_hex_error)?;
        if b.len() != 32 {
            return Err(AppError::new("Invalid input length"));
        }
        let mut arr = [0u8; 32];
        arr.copy_from_slice(&b);
        topic_bytes.push(arr);
    }

    // Validate first topic for non-anonymous events
    let mut topic_iter = topic_bytes.iter();
    if !event.anonymous {
        let first = topic_iter.next().ok_or_else(|| AppError::new("Invalid data"))?;
        if first != &event.topic_hash() {
            return Err(AppError::new("Invalid data"));
        }
    }

    // Separate indexed and non-indexed params
    let mut indexed_params: Vec<&contract::Param> = Vec::new();
    let mut data_params: Vec<&contract::Param> = Vec::new();
    for p in &event.inputs {
        if p.indexed {
            indexed_params.push(p);
        } else {
            data_params.push(p);
        }
    }

    // Remaining topics correspond to indexed params (in order)
    let remaining_topics: Vec<&[u8; 32]> = topic_iter.collect();
    if remaining_topics.len() != indexed_params.len() {
        return Err(AppError::new("Invalid data"));
    }

    // Parse data bytes
    let data = hex::decode(data_hex).map_err(wrap_hex_error)?;
    let data_types: Vec<abi_type::ParamType> = data_params.iter().map(|p| p.kind.clone()).collect();
    let data_tokens = decoder::decode(&data_types, &data).map_err(|e| AppError::new(e.0))?;

    // Combine: interleave in original input order
    let mut data_iter = data_tokens.into_iter();
    let mut topic_iter = remaining_topics.into_iter();

    for p in &event.inputs {
        let tok = if p.indexed {
            let t = topic_iter.next().unwrap();
            topic_to_token(&p.kind, t)
        } else {
            data_iter.next().unwrap()
        };
        let name = if p.name.is_empty() { format!("{}", p.kind) } else { p.name.clone() };
        println!("{} {}", name, token::format_token(&tok));
    }
    Ok(ExitCode::from(0))
}

fn topic_to_token(kind: &abi_type::ParamType, topic: &[u8; 32]) -> token::Token {
    // For dynamic indexed types (string/bytes/arrays/tuples), the topic is the hash;
    // we display it as raw bytes.
    use abi_type::ParamType::*;
    match kind {
        Address => {
            let mut a = [0u8; 20];
            a.copy_from_slice(&topic[12..]);
            token::Token::Address(a)
        }
        Bool => token::Token::Bool(topic[31] == 1),
        Uint(_) => { token::Token::Uint(*topic) }
        Int(_) => { token::Token::Int(*topic) }
        FixedBytes(n) => { token::Token::FixedBytes(topic[..*n].to_vec()) }
        _ => token::Token::FixedBytes(topic.to_vec()),
    }
}

// ============================================================================
// Lookup helpers
// ============================================================================

fn find_function<'a>(contract: &'a contract::Contract, sig: &str) -> Result<&'a contract::Function, AppError> {
    if sig.contains('(') {
        // Treat as full signature
        for f in &contract.functions {
            if f.signature_with_outputs() == sig || f.signature() == sig {
                return Ok(f);
            }
        }
        return Err(AppError::new(format!("invalid function signature `{}`", sig)));
    }
    // Name lookup
    let matches: Vec<&contract::Function> = contract.functions.iter().filter(|f| f.name == sig).collect();
    if matches.is_empty() {
        return Err(AppError::new(format!("Invalid name: {}", sig)));
    }
    if matches.len() > 1 {
        return Err(AppError::new(format!("More than one function found for name `{}`, try providing the full signature", sig)));
    }
    Ok(matches[0])
}

fn find_event<'a>(contract: &'a contract::Contract, sig: &str) -> Result<&'a contract::Event, AppError> {
    if sig.contains('(') {
        let hash = keccak::keccak256(sig.as_bytes());
        for e in &contract.events {
            if e.signature() == sig {
                return Ok(e);
            }
        }
        let short = format!("0x{}…{}", &hex::encode(&hash[..])[..4], &hex::encode(&hash[..])[60..]);
        return Err(AppError::new(format!("Invalid signature `{}`", short)));
    }
    let matches: Vec<&contract::Event> = contract.events.iter().filter(|e| e.name == sig).collect();
    if matches.is_empty() {
        return Err(AppError::new(format!("Invalid name: {}", sig)));
    }
    if matches.len() > 1 {
        return Err(AppError::new(format!("More than one event found for name `{}`, try providing the full signature", sig)));
    }
    Ok(matches[0])
}

// ============================================================================
// Error wrapping
// ============================================================================

fn wrap_token_error(e: token::TokenError) -> AppError {
    match e {
        token::TokenError::HexError(h) => {
            let src: Box<dyn std::error::Error + Send + Sync> = Box::new(h);
            AppError::with_cause(format!("Hex parsing error: {}", src), src)
        }
        token::TokenError::UintError(u) => {
            AppError::new(format!("Uint parse error: {}", u))
        }
        token::TokenError::InvalidData => AppError::new("Invalid data"),
    }
}

fn wrap_hex_error(e: hex::HexError) -> AppError {
    let msg = format!("{}", e);
    let src: Box<dyn std::error::Error + Send + Sync> = Box::new(e);
    AppError::with_cause(msg, src)
}

fn wrap_serialization_error(e: Box<dyn std::error::Error>) -> AppError {
    let msg = format!("Serialization error: {}", e);
    AppError { msg: format!("{}", msg), source: None }.set_source_from_string(format!("{}", e))
}

impl AppError {
    fn set_source_from_string(mut self, src: String) -> Self {
        let src_err: Box<dyn std::error::Error + Send + Sync> = Box::new(AppError::new(src));
        self.source = Some(src_err);
        self
    }
}
