#[derive(Debug)]
pub struct AppError {
    pub msg: String,
    pub source: Option<Box<dyn std::error::Error + Send + Sync>>,
}

impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.msg)
    }
}

impl AppError {
    pub fn new(msg: impl Into<String>) -> Self {
        AppError { msg: msg.into(), source: None }
    }
    pub fn with_cause(msg: impl Into<String>, source: Box<dyn std::error::Error + Send + Sync>) -> Self {
        AppError { msg: msg.into(), source: Some(source) }
    }
    pub fn source(&self) -> Option<&(dyn std::error::Error + Send + Sync)> {
        self.source.as_deref()
    }
}

