            "-l" | "--lenient" => { lenient = true; i += 1; }
            "-p" => {
                if i + 1 >= args.len() {
                    return Err(AppError::new("missing value for -p"));
                }
                params.push(args[i + 1].clone());
                i += 2;
            }
            _ => {
                if abi_path.is_none() {
                    abi_path = Some(a.clone());
                } else if sig.is_none() {
