# Add the handle_help function
cat >> src/main.rs <<'EOF'

fn handle_help(args: &[String], path: &[&str]) -> Result<ExitCode, AppError> {
    // path is e.g. ["executable", "help"] or ["executable", "encode", "help"]
    // Reconstruct "<prog> <sub*> help" usage
    if args.is_empty() {
        // Print the help message for the immediate parent
        print_help_for_path(&path[..path.len() - 1]);
        return Ok(ExitCode::from(0));
    }
    let mut current_path: Vec<&str> = path.iter().copied().take(path.len() - 1).collect();
    for (i, a) in args.iter().enumerate() {
        if a == "help" {
            // Help help message
            let mut new_path = current_path.clone();
            new_path.push("help");
            print_help_help(&new_path);
            return Ok(ExitCode::from(0));
        }
        // Look up subcommand within current_path
        let next = match (current_path.as_slice(), a.as_str()) {
            (["executable"], "encode") => Some("encode"),
            (["executable"], "decode") => Some("decode"),
            (["executable", "encode"], "function") => Some("function"),
            (["executable", "encode"], "params") => Some("params"),
            (["executable", "decode"], "function") => Some("function"),
            (["executable", "decode"], "params") => Some("params"),
            (["executable", "decode"], "log") => Some("log"),
            _ => None,
        };
        match next {
            Some(_) => {
                current_path.push(leak_str(a.clone()));
                if i + 1 == args.len() {
                    print_help_for_path(&current_path);
                    return Ok(ExitCode::from(0));
                }
            }
            None => {
                let mut usage_path = current_path.clone();
                usage_path.push("help");
                help_unknown_subcommand(a, &usage_path);
                return Ok(ExitCode::from(1));
            }
        }
    }
    print_help_for_path(&current_path);
    Ok(ExitCode::from(0))
}

fn leak_str(s: String) -> &'static str {
    Box::leak(s.into_boxed_str())
}

fn print_help_for_path(path: &[&str]) {
    match path {
        &["executable"] => print_top_help(),
        &["executable", "encode"] => print_encode_help(),
        &["executable", "encode", "function"] => print_encode_function_help(),
        &["executable", "encode", "params"] => print_encode_params_help(),
        &["executable", "decode"] => print_decode_help(),
        &["executable", "decode", "function"] => print_decode_function_help(),
        &["executable", "decode", "params"] => print_decode_params_help(),
        &["executable", "decode", "log"] => print_decode_log_help(),
        _ => print_top_help(),
    }
}

fn print_help_help(path: &[&str]) {
    // path ends with "help", e.g., ["executable", "help"] or ["executable", "encode", "help"]
    let prefix = path[..path.len() - 1].join(" ");
    let name = path.join("-");
    println!(
"{name} 
Prints this message or the help of the given subcommand(s)

USAGE:
    {prefix} help [subcommand]...

ARGS:
    <subcommand>...    The subcommand whose help message to display");
}

fn help_unknown_subcommand(s: &str, usage_path: &[&str]) {
    eprintln!("error: The subcommand '{}' wasn't recognized", s);
    eprintln!();
    eprintln!("USAGE:");
    eprintln!("\t{} <subcommands>...", usage_path.join(" "));
    eprintln!();
    eprintln!("For more information try --help");
}
