// Minimal JSON parser with position tracking for objects.

use std::collections::BTreeMap;
use std::fmt;

#[derive(Debug, Clone)]
pub enum Value {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Value>),
    Object(Object),
}

#[derive(Debug, Clone)]
pub struct Object {
    pub fields: BTreeMap<String, Value>,
    /// 1-indexed line and column of the character immediately following the closing `}`
    /// (or the position of `}` if the string ends there). Non-whitespace preferred.
    pub close_line: usize,
    pub close_col: usize,
}

#[derive(Debug)]
pub struct JsonError {
    pub message: String,
}

impl fmt::Display for JsonError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl std::error::Error for JsonError {}

struct Parser<'a> {
    input: &'a [u8],
    pos: usize,
    line: usize,
    col: usize,
}

pub fn parse(s: &str) -> Result<Value, JsonError> {
    let mut p = Parser { input: s.as_bytes(), pos: 0, line: 1, col: 1 };
    p.skip_ws();
    let v = p.parse_value()?;
    p.skip_ws();
    if p.pos != p.input.len() {
        return Err(JsonError { message: format!("trailing data at {}:{}", p.line, p.col) });
    }
    Ok(v)
}

impl<'a> Parser<'a> {
    fn advance(&mut self) {
        if self.pos < self.input.len() {
            if self.input[self.pos] == b'\n' {
                self.line += 1;
                self.col = 1;
            } else {
                self.col += 1;
            }
            self.pos += 1;
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b' ' | b'\t' | b'\n' | b'\r' => self.advance(),
                _ => break,
            }
        }
    }

    fn err(&self, msg: &str) -> JsonError {
        JsonError { message: format!("{} at line {} column {}", msg, self.line, self.col) }
    }

    fn parse_value(&mut self) -> Result<Value, JsonError> {
        self.skip_ws();
        if self.pos >= self.input.len() {
            return Err(self.err("unexpected end of input"));
        }
        match self.input[self.pos] {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => self.parse_string().map(Value::String),
            b't' | b'f' => self.parse_bool(),
            b'n' => self.parse_null(),
            b'-' | b'0'..=b'9' => self.parse_number(),
            c => Err(self.err(&format!("unexpected character '{}'", c as char))),
        }
    }

    fn parse_object(&mut self) -> Result<Value, JsonError> {
        self.advance(); // '{'
        let mut map = BTreeMap::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b'}' {
            self.advance();
            // Capture position just after `}`, skipping whitespace
            let (cl, cc) = self.peek_after_ws();
            return Ok(Value::Object(Object { fields: map, close_line: cl, close_col: cc }));
        }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.pos >= self.input.len() || self.input[self.pos] != b':' {
                return Err(self.err("expected ':'"));
            }
            self.advance();
            let value = self.parse_value()?;
            map.insert(key, value);
            self.skip_ws();
            if self.pos >= self.input.len() {
                return Err(self.err("unterminated object"));
            }
            match self.input[self.pos] {
                b',' => { self.advance(); continue; }
                b'}' => {
                    self.advance();
                    let (cl, cc) = self.peek_after_ws();
                    return Ok(Value::Object(Object { fields: map, close_line: cl, close_col: cc }));
                }
                c => return Err(self.err(&format!("expected ',' or '}}' got '{}'", c as char))),
            }
        }
    }

    fn peek_after_ws(&self) -> (usize, usize) {
        // Look ahead from self.pos for next non-whitespace char, return its line/col
        let mut pos = self.pos;
        let mut line = self.line;
        let mut col = self.col;
        while pos < self.input.len() {
            let c = self.input[pos];
            if c == b' ' || c == b'\t' || c == b'\r' {
                col += 1;
                pos += 1;
            } else if c == b'\n' {
                line += 1;
                col = 1;
                pos += 1;
            } else {
                break;
            }
        }
        (line, col)
    }

    fn parse_array(&mut self) -> Result<Value, JsonError> {
        self.advance(); // '['
        let mut arr = Vec::new();
        self.skip_ws();
        if self.pos < self.input.len() && self.input[self.pos] == b']' {
            self.advance();
            return Ok(Value::Array(arr));
        }
        loop {
            let v = self.parse_value()?;
            arr.push(v);
            self.skip_ws();
            if self.pos >= self.input.len() {
                return Err(self.err("unterminated array"));
            }
            match self.input[self.pos] {
                b',' => { self.advance(); continue; }
                b']' => { self.advance(); return Ok(Value::Array(arr)); }
                c => return Err(self.err(&format!("expected ',' or ']' got '{}'", c as char))),
            }
        }
    }

    fn parse_string(&mut self) -> Result<String, JsonError> {
        if self.pos >= self.input.len() || self.input[self.pos] != b'"' {
            return Err(self.err("expected '\"'"));
        }
        self.advance();
        let mut out = Vec::new();
        while self.pos < self.input.len() {
            match self.input[self.pos] {
                b'"' => { self.advance(); return Ok(String::from_utf8_lossy(&out).into_owned()); }
                b'\\' => {
                    self.advance();
                    if self.pos >= self.input.len() {
                        return Err(self.err("unterminated escape"));
                    }
                    match self.input[self.pos] {
                        b'"' => { out.push(b'"'); self.advance(); }
                        b'\\' => { out.push(b'\\'); self.advance(); }
                        b'/' => { out.push(b'/'); self.advance(); }
                        b'n' => { out.push(b'\n'); self.advance(); }
                        b't' => { out.push(b'\t'); self.advance(); }
                        b'r' => { out.push(b'\r'); self.advance(); }
                        b'b' => { out.push(0x08); self.advance(); }
                        b'f' => { out.push(0x0c); self.advance(); }
                        b'u' => {
                            self.advance();
                            if self.pos + 4 > self.input.len() {
                                return Err(self.err("bad unicode escape"));
                            }
                            let hex = std::str::from_utf8(&self.input[self.pos..self.pos + 4])
                                .map_err(|_| self.err("bad unicode escape"))?;
                            let code = u32::from_str_radix(hex, 16)
                                .map_err(|_| self.err("bad unicode escape"))?;
                            if let Some(c) = char::from_u32(code) {
                                let mut buf = [0u8; 4];
                                let s = c.encode_utf8(&mut buf);
                                out.extend_from_slice(s.as_bytes());
                            }
                            for _ in 0..4 { self.advance(); }
                        }
                        c => return Err(self.err(&format!("bad escape '\\{}'", c as char))),
                    }
                }
                _ => { out.push(self.input[self.pos]); self.advance(); }
            }
        }
        Err(self.err("unterminated string"))
    }

    fn parse_bool(&mut self) -> Result<Value, JsonError> {
        if self.input[self.pos..].starts_with(b"true") {
            for _ in 0..4 { self.advance(); }
            Ok(Value::Bool(true))
        } else if self.input[self.pos..].starts_with(b"false") {
            for _ in 0..5 { self.advance(); }
            Ok(Value::Bool(false))
        } else {
            Err(self.err("invalid bool"))
        }
    }

    fn parse_null(&mut self) -> Result<Value, JsonError> {
        if self.input[self.pos..].starts_with(b"null") {
            for _ in 0..4 { self.advance(); }
            Ok(Value::Null)
        } else {
            Err(self.err("invalid null"))
        }
    }

    fn parse_number(&mut self) -> Result<Value, JsonError> {
        let start = self.pos;
        if self.input[self.pos] == b'-' {
            self.advance();
        }
        while self.pos < self.input.len() {
            let c = self.input[self.pos];
            if c.is_ascii_digit() || c == b'.' || c == b'e' || c == b'E' || c == b'+' || c == b'-' {
                self.advance();
            } else {
                break;
            }
        }
        let s = std::str::from_utf8(&self.input[start..self.pos])
            .map_err(|_| self.err("invalid number"))?;
        let n: f64 = s.parse().map_err(|_| self.err("invalid number"))?;
        Ok(Value::Number(n))
    }
}

impl Value {
    pub fn as_array(&self) -> Option<&Vec<Value>> {
        if let Value::Array(a) = self { Some(a) } else { None }
    }
    pub fn as_object(&self) -> Option<&Object> {
        if let Value::Object(o) = self { Some(o) } else { None }
    }
    pub fn as_str(&self) -> Option<&str> {
        if let Value::String(s) = self { Some(s) } else { None }
    }
    pub fn as_bool(&self) -> Option<bool> {
        if let Value::Bool(b) = self { Some(*b) } else { None }
    }
}
