                let inputs = parse_params(obj.fields.get("inputs"))?;
                let outputs = parse_params(obj.fields.get("outputs"))?;
                contract.functions.push(Function { name, inputs, outputs });
            }
            "event" => {
                require_field(obj, "name")?;
                require_field(obj, "inputs")?;
                require_field(obj, "anonymous")?;
                let name = obj.fields.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
                let inputs = parse_params(obj.fields.get("inputs"))?;
                let anonymous = obj.fields.get("anonymous").and_then(|v| v.as_bool()).unwrap_or(false);
                contract.events.push(Event { name, inputs, anonymous });
            }
            "constructor" => {
                require_field(obj, "inputs")?;
                let inputs = parse_params(obj.fields.get("inputs"))?;
                contract.constructor = Some(Constructor { inputs });
            }
            "fallback" | "receive" | "error" => {
