            for (i, p) in self.outputs.iter().enumerate() {
                if i > 0 { s.push(','); }
                s.push_str(&format!("{}", p.kind));
            }
            s.push(')');
        }
        s
    }

    pub fn selector(&self) -> [u8; 4] {
        let sig = self.signature();
        let h = crate::keccak::keccak256(sig.as_bytes());
        [h[0], h[1], h[2], h[3]]
    }
}

