        let mut s = String::new();
        s.push_str(&self.name);
        s.push('(');
        for (i, p) in self.inputs.iter().enumerate() {
            if i > 0 { s.push(','); }
            s.push_str(&format!("{}", p.kind));
        }
        s.push(')');
        s
    }

    pub fn topic_hash(&self) -> [u8; 32] {
        crate::keccak::keccak256(self.signature().as_bytes())
    }
}
